import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.DaGSOal_.js";const p=JSON.parse('{"title":"H","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/h.md","filePath":"glossaire-a-z/h.md"}'),n={name:"glossaire-a-z/h.md"};function s(o,e,l,c,d,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H&quot;">​</a></h1><h2 id="hard-fork-fr-fourche-dure" tabindex="-1">Hard Fork (fr : Fourche dure) <a class="header-anchor" href="#hard-fork-fr-fourche-dure" aria-label="Permalink to &quot;Hard Fork (fr : Fourche dure)&quot;">​</a></h2><p>Une mise à niveau du protocole d’une blockchain qui n’est pas rétrocompatible et qui exige que les participants adoptent les nouvelles règles pour rester sur la même chaîne. Si aucun consensus n’est atteint, un hard fork peut entraîner une séparation permanente en plusieurs blockchains distinctes, comme cela s’est produit avec Bitcoin et Bitcoin Cash.</p><p>→ <a href="https://docs.cardano.org/about-cardano/evolution/about-hard-forks" target="_blank" rel="noreferrer">About hard forks — Cardano Docs</a></p><h2 id="hard-fork-combinator-fr-combinateur-de-fourche-dure" tabindex="-1">Hard Fork Combinator (fr : Combinateur de fourche dure) <a class="header-anchor" href="#hard-fork-combinator-fr-combinateur-de-fourche-dure" aria-label="Permalink to &quot;Hard Fork Combinator (fr : Combinateur de fourche dure)&quot;">​</a></h2><p>Le Hard Fork Combinator est le mécanisme propre à Cardano qui permet de combiner plusieurs versions du protocole au sein d’une seule blockchain. Il permet des transitions fluides entre les ères, par exemple de Byron à Shelley ou de Shelley à Allegra, sans provoquer de fragmentation du réseau ni d’interruption.</p><h2 id="hard-fork-initiation-fr-initiation-d-une-fourche-dure" tabindex="-1">Hard Fork Initiation (fr : Initiation d’une fourche dure) <a class="header-anchor" href="#hard-fork-initiation-fr-initiation-d-une-fourche-dure" aria-label="Permalink to &quot;Hard Fork Initiation (fr : Initiation d’une fourche dure)&quot;">​</a></h2><p>Un type d’action de gouvernance défini par la CIP-1694, qui programme et déclenche une fourche dure de Cardano au moyen d’un vote sur la chaîne.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-1694" target="_blank" rel="noreferrer">CIP-1694 — Spécification officielle</a></p><h2 id="hash-function-fr-fonction-de-hachage" tabindex="-1">Hash Function (fr : Fonction de hachage) <a class="header-anchor" href="#hash-function-fr-fonction-de-hachage" aria-label="Permalink to &quot;Hash Function (fr : Fonction de hachage)&quot;">​</a></h2><p>Un algorithme cryptographique qui convertit des données d’entrée de taille quelconque en une sortie de taille fixe appelée <em>hash</em> (empreinte). Dans les blockchains, les fonctions de hachage servent à sécuriser les données, à relier les blocs entre eux et à vérifier les transactions. Même de petites modifications des données d’entrée produisent des empreintes très différentes. Cardano utilise principalement les fonctions de hachage cryptographiques Blake2b et SHA-256.</p><h2 id="hashing-fr-hachage" tabindex="-1">Hashing (fr : Hachage) <a class="header-anchor" href="#hashing-fr-hachage" aria-label="Permalink to &quot;Hashing (fr : Hachage)&quot;">​</a></h2><p>Le processus consistant à appliquer une fonction de hachage cryptographique à des données d’entrée pour générer une sortie de taille fixe appelée <em>hash</em> (empreinte). Dans les blockchains, le hachage sécurise les transactions et les blocs, garantit l’intégrité des données et rend pratiquement impossible la modification de données passées sans que celle-ci soit détectée.</p><h2 id="hash-rate-fr-taux-de-hachage" tabindex="-1">Hash Rate (fr : Taux de hachage) <a class="header-anchor" href="#hash-rate-fr-taux-de-hachage" aria-label="Permalink to &quot;Hash Rate (fr : Taux de hachage)&quot;">​</a></h2><p>La mesure de la puissance de calcul utilisée dans les blockchains fondées sur la preuve de travail (<em>Proof of Work</em>, PoW), comme Bitcoin, pour résoudre des énigmes cryptographiques et sécuriser le réseau.</p><h2 id="haskell" tabindex="-1">Haskell <a class="header-anchor" href="#haskell" aria-label="Permalink to &quot;Haskell&quot;">​</a></h2><p>Un langage de programmation fonctionnel reconnu pour son système de types fort et son approche fondée sur des principes mathématiques. Le protocole central de Cardano est largement implémenté en Haskell afin de favoriser un haut niveau d’assurance et de fiabilité dans les applications blockchain.</p><p>→ <a href="https://www.haskell.org/" target="_blank" rel="noreferrer">Site officiel de Haskell</a></p><h2 id="hierarchical-deterministic-wallets-hd-wallets-fr-portefeuilles-hierarchiques-deterministes" tabindex="-1">Hierarchical Deterministic Wallets (HD Wallets) (fr : Portefeuilles hiérarchiques déterministes) <a class="header-anchor" href="#hierarchical-deterministic-wallets-hd-wallets-fr-portefeuilles-hierarchiques-deterministes" aria-label="Permalink to &quot;Hierarchical Deterministic Wallets (HD Wallets) (fr : Portefeuilles hiérarchiques déterministes)&quot;">​</a></h2><p>Les portefeuilles hiérarchiques déterministes génèrent un arbre structuré de clés privées et publiques à partir d’une seule phrase de récupération. Cela permet aux utilisateurs de gérer plusieurs adresses de manière sécurisée et pratique, puisque toutes les clés et adresses peuvent être restaurées à partir de la phrase de récupération d’origine.</p><h2 id="hot-wallet-fr-portefeuille-connecte" tabindex="-1">Hot Wallet (fr : Portefeuille connecté) <a class="header-anchor" href="#hot-wallet-fr-portefeuille-connecte" aria-label="Permalink to &quot;Hot Wallet (fr : Portefeuille connecté)&quot;">​</a></h2><p>Un portefeuille connecté à Internet, qui facilite les transactions fréquentes, mais qui est davantage exposé aux risques de sécurité. Les portefeuilles mobiles, de bureau ou accessibles sur le Web qui conservent des clés privées dans un environnement connecté en sont des exemples.</p><h2 id="hybrid-blockchain-fr-blockchain-hybride" tabindex="-1">Hybrid Blockchain (fr : Blockchain hybride) <a class="header-anchor" href="#hybrid-blockchain-fr-blockchain-hybride" aria-label="Permalink to &quot;Hybrid Blockchain (fr : Blockchain hybride)&quot;">​</a></h2><p>Une blockchain hybride combine des éléments de blockchains publiques sans permission et de blockchains privées avec permission. Elle permet de rendre certaines données ou fonctions ouvertes et transparentes, tout en réservant d’autres éléments aux participants autorisés. Ce modèle est souvent utilisé pour concilier transparence, efficacité et confidentialité dans les cas d’usage des entreprises ou des consortiums.</p><h2 id="hydra" tabindex="-1">Hydra <a class="header-anchor" href="#hydra" aria-label="Permalink to &quot;Hydra&quot;">​</a></h2><p>Une solution de mise à l’échelle de couche 2 conçue pour Cardano, qui vise à augmenter le débit et l’efficacité en traitant les transactions hors chaîne dans des unités appelées <em>Hydra Heads</em>. Ces têtes Hydra permettent des transactions rapides et peu coûteuses, tout en assurant le règlement final sur la chaîne principale de Cardano. Elles peuvent notamment prendre en charge des applications telles que les micropaiements et les interactions en temps réel.</p><p>→ <a href="https://hydra.family/head-protocol/" target="_blank" rel="noreferrer">Documentation officielle du protocole Hydra</a></p><h2 id="hydra-head-fr-tete-hydra" tabindex="-1">Hydra Head (fr : Tête Hydra) <a class="header-anchor" href="#hydra-head-fr-tete-hydra" aria-label="Permalink to &quot;Hydra Head (fr : Tête Hydra)&quot;">​</a></h2><p>Une tête Hydra est un mini-registre hors chaîne du protocole de couche 2 Hydra de Cardano, dans lequel un petit groupe de participants peut traiter des transactions rapidement et à faible coût. L’état final de la tête peut ensuite être réglé de manière sécurisée sur la chaîne principale de Cardano.</p><p>→ <a href="https://hydra.family/head-protocol/" target="_blank" rel="noreferrer">Hydra Head Protocol — Documentation officielle</a></p>',30)])])}const f=a(n,[["render",s]]);export{p as __pageData,f as default};
